from wl_viz import *

V = {}

def weight_frame(k):
    w = [128, 64, 32, 16, 8, 4, 2, 1]
    row = [[("1" if i < k else "0"), "n" if i < k else "g"] for i in range(8)]
    acc = sum(w[:k])
    return F(tbl(w, [row], rh=False), "→".join(str(sum(w[:j + 1])) for j in range(k)), f"{k}")

def mask_frame(octs, label, r):
    bs = ipbin(*octs)
    ones = bs.count("1")
    c = [[ch, "n" if ch == "1" else "g"] for ch in bs]
    return F(bits(c, lg=[["n", "网络前缀（1）"], ["g", "主机号（0）"]]), r + f"　1 的个数 = {ones} → 前缀长度 {ones}", label)

V["2-1-1"] = [
    steps([weight_frame(k) for k in range(1, 9)]),
    tabs([
        mask_frame((192, 0, 0, 0), "(1) 192.0.0.0", "192.0.0.0"),
        mask_frame((240, 0, 0, 0), "(2) 240.0.0.0", "240.0.0.0"),
        mask_frame((255, 224, 0, 0), "(3) 255.224.0.0", "255.224.0.0（8+3=11）"),
        mask_frame((255, 255, 255, 252), "(4) 255.255.255.252", "255.255.255.252（8+8+8+6=30）"),
    ], "掩码"),
    steps([
        F(bits([[ch, "n"] for ch in "1" * 32]), "255 全 1"),
        F(bits([[ch, "n" if i < 30 else "g x"] for i, ch in enumerate("1" * 30 + "00")], lg=[["n", "1"], ["g", "末尾 2 个 0"]]), "255 − 3 = 252：从末尾去掉 2 个 1"),
        F(bits([[ch, "n" if i < 30 else "g"] for i, ch in enumerate("1" * 30 + "00")]), "32 − 2 = 30"),
    ]),
]

# ---- 2-2-1 ----
OPTS = [("(1)", "86.33.224.123", 33), ("(2)", "86.79.65.216", 79), ("(3)", "86.58.119.74", 58), ("(4)", "86.68.206.154", 68)]
def cmp_frame(no, ip, b2):
    tgt = b8(32); opt = b8(b2)
    t = [[c, "s"] for c in tgt[:4]] + [[c, "g"] for c in tgt[4:]]
    o = [[c, ("h" if c == tgt[i] else "r") if i < 4 else "g"] for i, c in enumerate(opt)]
    ok = opt[:4] == tgt[:4]
    return F([bits(t, 8, 8, x="86.32 的第 2 字节 32"), bits(o, 8, 8, x=f"{no} {ip} 的第 2 字节 {b2}")],
             f"{b2} = {opt[:4]} {opt[4:]} → {opt[:4]} {'✔ 匹配' if ok else '✘'}", f"{no}")
f221 = and_frames("86.33.224.123", ipbin(86, 33, 224, 123), "255.240.0.0", ipbin(255, 240, 0, 0), "AND 结果", 8, "w",
                  final_r="86.33.224.123 AND 255.240.0.0 = 86.32.0.0，与 86.32.0.0 相同 ✔ 匹配")
V["2-2-1"] = [
    static(F(bits([[ "", "s"]] * 4 + [["", "g"]] * 4, 8, 8, lg=[["s", "前 4 位：比较区"], ["g", "后 4 位：不管"]]), "/12 = 第 1 字节 86 的 8 位 + 第 2 字节的前 4 位")),
    steps([cmp_frame(*o) for o in OPTS]),
    steps(f221[0]),
]

# ---- 2-3-1 ----
A140 = ipbin(140, 120, 84, 24)
def block_140(hi_byte=None, host_fill=None):
    c = []
    for i, ch in enumerate(A140):
        k = "n" if i < 20 else "h"
        if hi_byte is not None and i // 8 == hi_byte: k += " hi"
        c.append([ch, k])
    return bits(c, lg=[["n", "网络前缀 20 位"], ["h", "主机号 12 位"]])
def host_block(fill):
    prefix = A140[:20]
    c = [[ch, "n"] for ch in prefix] + [[fill, "h"]] * 12
    return bits(c, lg=[["n", "前缀不变"], ["h", f"主机号 12 位全 {fill}"]])
def c_slider():
    fr = []
    for k in range(1, 17):
        sg = [{"a": 80 + i, "b": 81 + i, "c": ("n" if i % 2 == 0 else "p") + ("" if i < k else " dim"), "x": f"{80 + i}"} for i in range(16)]
        fr.append(F(sc(80, 96, sg, tk=[[80, "140.120.80.0"], [96, "140.120.95.255"]], lg=False), f"{k} / 16 个 C 类" if k < 16 else "16 个 C 类", f"{k}"))
    return fr
V["2-3-1"] = [
    steps([
        F(block_140(), "前 20 位 = 140.120 + 0101；主机号 12 位 = 32 − 20"),
        F(block_140(2), "第 3 字节 84 = 0101 0100：前缀 4 位 + 主机 4 位"),
    ]),
    tabs([
        F(host_block("0"), "140.120.0101 0000.00000000 = 140.120.80.0", "全0"),
        F(host_block("1"), "140.120.0101 1111.11111111 = 140.120.95.255", "全1"),
    ], "主机号 12 位"),
    slider(c_slider(), "C 类个数"),
]

