# ---- 2-5-1 / 2-5-2 ----
B156 = lambda third, fourth: ipbin(156, 16, third, fourth)
def rowbits(bs, hi=None, tag=None):
    c = [[ch, "p" if i < 20 else "h"] for i, ch in enumerate(bs)]
    return bits(c, lg=None)
LST = [("156.16.32.0", B156(32, 0), "最小地址（网络地址）"), ("156.16.32.1", B156(32, 1), "最小主机 IP"),
       ("156.16.47.254", B156(47, 254), "最大主机 IP"), ("156.16.47.255", B156(47, 255), "最大地址（广播地址）")]
def addr_table(hl=None):
    rows = []
    for i, (ip, bs, tag) in enumerate(LST):
        cls = "hi" if hl == i else ""
        rows.append([[ip, cls], [f"{bs[:20]} | {bs[20:]}", cls]])
    return tbl(["地址", "前 20 位 | 后 12 位"], rows, rh=False)
V["2-5-1"] = [
    static(F([addr_table(), bits(cells((20, "p"), (12, "h")), lg=[["p", "前 20 位：前缀"], ["h", "后 12 位：主机号"]])], "156.16.32.0/20 组成的地址块（共 2^12 个地址）")),
    tabs([
        F([addr_table(0), bits(cells(("0" * 12, "h")) , nc=8, lg=[["h", "主机号 12 位全 0"]])], "最小地址 156.16.32.0：主机号全 0 → 网络地址", "最小地址"),
        F([addr_table(3), bits(cells(("1" * 12, "h")), nc=8, lg=[["h", "主机号 12 位全 1"]])], "最大地址 156.16.47.255：主机号全 1 → 广播地址", "最大地址"),
        F([addr_table(1)], "最小主机 IP = 网络地址 + 1 = 156.16.32.1", "第 2 行"),
        F([addr_table(2)], "最大主机 IP = 广播地址 − 1 = 156.16.47.254", "倒数第 2 行"),
    ], "地址"),
    steps([
        F(bits(cells(("0" * 12, "h")), nc=12, cols=12, by=12), "2^12 → 4096"),
        F(bits([["", "h"]] + [["", "h"]] * 10 + [["", "h"]], nc=12, cols=12, by=12), "4096 − 2"),
        F(bits([["", "g x"]] + [["", "h"]] * 10 + [["", "g x"]], nc=12, cols=12, by=12, lg=[["g", "网络地址、广播地址（各划掉一格）"], ["h", "可指派"]]), "2^12 − 2 = 4094"),
    ]),
]
